import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PINS = [2, 3, 4]
INTERVAL = 60

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PINS:
            dev = OutputDevice(pin)
            devices.append(dev)
            dev.off()
        print(f"GPIO {PINS} configured as outputs (initial LOW).")

        while _running:
            for dev in devices:
                if dev.closed:
                    print(f"Error: GPIO {dev.pin.number} closed unexpectedly.", file=sys.stderr)
                    _running = False
                    break
            if not _running:
                break
            print(f"GPIO {PINS} -> LOW")
            time.sleep(0.5)
            if not _running:
                break
            for dev in devices:
                if dev.closed:
                    break
            if not _running:
                break
            print(f"GPIO {PINS} -> HIGH")
            time.sleep(0.5)
    except GPIOZeroError as exc:
        print(f"GPIO error: {exc}", file=sys.stderr)
        sys.exit(1)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        for dev in devices:
            try:
                dev.close()
            except DeviceClosed:
                pass
            except Exception:
                pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

