import signal
import sys
import time

from luma.core.interface.serial import sg
from luma.core.render import canvas
from luma.oled.device import ssd1306

# --- Configuration -----------------------------------------------------------
SERIAL_PORT = "/dev/serial0"
DEVICE_ID = 0x06

# --- Globals for cleanup -----------------------------------------------------
_running = True
_serial = None
_display = None


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def _init_display():
    """Open the serial port and initialise the SSD1306 OLED."""
    global _serial, _display
    try:
        _serial = sg(port=SERIAL_PORT, baudrate=115200, timeout=1)
    except Exception as exc:
        print(f"Error: cannot open serial port {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None

    try:
        _display = ssd1306(_serial, width=128, height=64, device_id=DEVICE_ID)
    except Exception as exc:
        print(f"Error: SSD1306 not detected on {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None

    return _display


def _write_to_display(value):
    """Render a single value to the OLED, rejecting invalid data."""
    if value is None:
        return
    try:
        with canvas(_display) as draw:
            draw.text((0, 0), str(value), fill="white")
    except Exception as exc:
        print(f"Warning: display write failed: {exc}", file=sys.stderr)


def _cleanup():
    """Release hardware resources."""
    global _display, _serial
    if _display is not None:
        try:
            _display.cleanup()
        except Exception:
            pass
        _display = None
    if _serial is not None:
        try:
            _serial.close()
        except Exception:
            pass
        _serial = None


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    _display = _init_display()
    if _display is None:
        print("Failed to initialise SSD1306. Exiting.", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    try:
        while _running:
            _write_to_display(
                100 + (time.time() % 10)
            )
            if _running:
                time.sleep(2)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

PWM_PINS = [1, 2, 3, 4]

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PWM_PINS:
            try:
                dev = PWMOutputDevice(pin, initial_value=0.0, frequency=100)
                devices.append(dev)
            except GPIOZeroError as exc:
                print(f"Failed to initialize PWM on GPIO{pin}: {exc}", file=sys.stderr)
                return 1

        while _running:
            values = []
            for dev in devices:
                try:
                    values.append(round(dev.value * 100, 1))
                except GPIOZeroError as exc:
                    print(f"Error reading GPIO{dev.pin}: {exc}", file=sys.stderr)
                    return 1
            print(" ".join(values))
            time.sleep(0.1)
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
        return 1
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
    return 0

if __name__ == "__main__":
    sys.exit(main())

