import serial
import time
import sys

SERIAL_PORT = '/dev/serial0'  # Raspberry Pi primary UART (maps to GPIO 14/15)
READ_INTERVAL_S = 5

def open_serial_port(port: str) -> serial.Serial | None:
    """Open the serial port; return None on failure."""
    try:
        ser = serial.Serial(
            port=port,
            baudrate=9600,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=1.0,
        )
        if not ser.is_open:
            print(f"Error: serial port {port} did not open.", file=sys.stderr)
            return None
        print(f"Opened {port} @ 9600 8N1.")
        return ser
    except serial.SerialException as exc:
        print(f"Error: cannot open {port}: {exc}", file=sys.stderr)
        return None

def read_and_print(ser: serial.Serial) -> bool:
    """Read one line from the device and print it. Return False on error."""
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Error: serial read failed: {exc}", file=sys.stderr)
        return False

    if not raw:
        # Timeout with no data — device may have disconnected.
        print("Warning: no data received (timeout).", file=sys.stderr)
        return False

    line = raw.decode('ascii', errors='replace').strip()
    if not line:
        return False

    print(f"Received: {line}")
    return True

def main() -> int:
    ser = open_serial_port(SERIAL_PORT)
    if ser is None:
        return 1

    try:
        while True:
            read_and_print(ser)
            time.sleep(READ_INTERVAL_S)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        try:
            if ser.is_open:
                ser.close()
                print("Serial port closed.")
        except Exception as exc:
            print(f"Warning: error closing serial port: {exc}", file=sys.stderr)

    return 0

if __name__ == "__main__":
    sys.exit(main())

