import signal
import sys
import time

from smbus2 import SMBus

BME280_I2C_ADDR = 0x76
READ_INTERVAL_S = 300

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_bme280_data(bus):
    """Read a 3-byte measurement from the BME280 over I2C."""
    try:
        data = bus.read_i2c_block_data(BME280_I2C_ADDR, 0x00, 3)
        return (data[0] << 16) | (data[1] << 8) | data[2]
    except OSError as exc:
        print(f"I2C read error: {exc}", file=sys.stderr)
        return None

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    bus = None
    try:
        bus = SMBus(1)
        print("BME280 reading started. Press Ctrl+C to stop.")
        while _running:
            data = read_bme280_data(bus)
            if data is not None:
                print(f"BME280 Data: {data}")
            time.sleep(READ_INTERVAL_S)
    except OSError as exc:
        print(f"Failed to open I2C bus 1: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass
        print("Program terminated.")

if __name__ == "__main__":
    main()

import serial
import sys

SERIAL_PORT = '/dev/serial0'
BAUD_RATE = 9600
TIMEOUT_SEC = 1.0

def validate_reading(raw_data: str) -> bool:
    """Return True if the raw data is a valid integer."""
    if not raw_data:
        return False
    try:
        return raw_data.isdigit()
    except Exception:
        return False

def main() -> int:
    ser = None
    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=TIMEOUT_SEC,
        )
        print(f"Opened {SERIAL_PORT} @ {BAUD_RATE} baud. Reading data...")

        while True:
            try:
                raw_bytes = ser.readline()
                if not raw_bytes:
                    continue

                raw_data = raw_bytes.decode('ascii', errors='replace').strip()
                if not raw_data:
                    continue

                if validate_reading(raw_data):
                    print(f"Valid reading: {raw_data}")
                else:
                    print(f"Invalid reading (not numeric): {raw_data}")

            except serial.SerialException as e:
                print(f"Serial communication error: {e}", file=sys.stderr)
                return 1
            except OSError as e:
                print(f"I/O error: {e}", file=sys.stderr)
                return 1

    except serial.SerialException as e:
        print(f"Failed to open {SERIAL_PORT}: {e}", file=sys.stderr)
        return 1
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        return 1
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

    return 0

if __name__ == "__main__":
    sys.exit(main())

