import time
import signal
import sys

BMP280_ADDR = 0x76

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def read_bmp280(bus):
    """Read a 16-bit two's-complement raw value from the BMP280."""
    data = bus.read_i2c_block_data(BMP280_ADDR, 0x18, 2)
    return (data[0] << 8) | data[1]

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        bus = smbus2.SMBus(1)
    except OSError as e:
        print(f"Failed to open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                raw = read_bmp280(bus)
                # BMP280 over-temperature and under-pressure protection bits
                if raw & 0x00010000:
                    print("Error: Over-temperature protection")
                if raw & 0x00020000:
                    print("Error: Under-pressure protection")
                # Temperature: bits 1-3 of the 16-bit value
                temp_raw = (raw >> 3) & 0x3FFF
                if temp_raw & 0x2000:
                    temp_raw -= 0x4000
                temp_c = temp_raw * 0.02 - 273.15
                print(f"Temperature: {temp_c:.2f} C")

                # Pressure: bits 4-15 of the 16-bit value
                press_raw = (raw >> 4) & 0x3FFF
                if press_raw & 0x2000:
                    press_raw -= 0x4000
                press_hpa = press_raw * 0.01 - 100.0
                print(f"Pressure: {press_hpa:.2f} hPa")
            except OSError as e:
                print(f"I2C read error: {e}", file=sys.stderr)

            for _ in range(5):
                if not _running:
                    break
                time.sleep(1)
    finally:
        bus.close()
        print("\nProgram terminated. I2C bus closed.")

if __name__ == "__main__":
    main()

