import signal
import sys
import smbus2

I2C_BUS = 1
MPU6050_ADDR = 0x68

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_mpu6050(bus, address):
    """Read a 16-bit big-endian word from the MPU6050 sensor register."""
    data = bus.read_word_data(address, 0x76)
    return (data << 8) | (data >> 8)

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = smbus2.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                raw = read_mpu6050(bus, MPU6050_ADDR)
                print(f"MPU6050 raw: 0x{raw:04X}")
            except OSError as e:
                print(f"Error: no response from MPU6050 at 0x{MPU6050_ADDR:02X}: {e}", file=sys.stderr)
                break
    finally:
        bus.close()

if __name__ == "__main__":
