import serial
import time
import signal
import sys

# Configuration
SERIAL_PORT = '/dev/serial0'  # Raspberry Pi primary UART (maps to GPIO 14/15)
READ_COUNT = 3
READ_INTERVAL = 1.0

# Global handle so signal handler can release it
_serial_conn = None
_running = True


def _cleanup():
    """Close the serial port if it is open."""
    global _serial_conn
    if _serial_conn is not None:
        try:
            if _serial_conn.is_open:
                _serial_conn.close()
                print("Serial port closed.")
        except Exception as e:
            print(f"Error closing serial port: {e}")
        finally:
            _serial_conn = None


def _signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global _running
    _running = False


def exchange_data(port, count, interval):
    """Exchange data with the connected device over the serial port."""
    global _serial_conn
    _serial_conn = port
    print(f"Connected to {port}")

    for i in range(count):
        if not _running:
            print("Shutdown requested; aborting readings.")
            break

        try:
            data = _serial_conn.readline().decode('ascii', errors='replace').strip()
            if data:
                print(f"Reading {i + 1}: {data}")
            else:
                print(f"Reading {i + 1}: <empty line>")
        except serial.SerialException as e:
            print(f"Serial read error on reading {i + 1}: {e}")
            break
        except OSError as e:
            print(f"I/O error on reading {i + 1}: {e}")
            break

        if i < count - 1:
            time.sleep(interval)

    _cleanup()


def main():
    """Entry point: set up signal handlers and run the exchange loop."""
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        exchange_data(SERIAL_PORT, READ_COUNT, READ_INTERVAL)
    except Exception as e:
        print(f"Fatal error: {e}")
        sys.exit(1)


if __name__ == "__main__":
    main()

