import serial
import time
import sys

SERIAL_PORT = '/dev/serial0'
READ_INTERVAL_S = 5

# Validity checks for the data we expect to receive.
# Replace these with actual checks for your device.
VALID_MIN_VALUE = 0
VALID_MAX_VALUE = 100

def read_data(ser):
    """Read one line from the serial port and return it as a string, or None on error/timeout."""
    try:
        raw = ser.readline()
    except serial.SerialException as exc:
        print(f"Serial read error: {exc}", file=sys.stderr)
        return None
    if not raw:
        return None
    try:
        return raw.decode('ascii', errors='replace').strip()
    except Exception as exc:
        print(f"Decode error: {exc}", file=sys.stderr)
        return None

def is_valid_data(data):
    """Return True if the data is within the expected range."""
    if not data:
        return False
    try:
        value = float(data)
    except ValueError:
        return False
    return VALID_MIN_VALUE <= value <= VALID_MAX_VALUE

def main():
    ser = None
    try:
        ser = serial.Serial(SERIAL_PORT, baudrate=9600, timeout=1)
        print(f"Opened {SERIAL_PORT} @ 9600 baud. Reading every {READ_INTERVAL_S} s.")
        while True:
            data = read_data(ser)
            if data is None:
                print("No data received (timeout or error).", file=sys.stderr)
                time.sleep(READ_INTERVAL_S)
                continue
            if is_valid_data(data):
                print(f"Valid data: {data}")
            else:
                print(f"Invalid data: {data}", file=sys.stderr)
            time.sleep(READ_INTERVAL_S)
    except serial.SerialException as exc:
        print(f"Serial port error: {exc}", file=sys.stderr)
        sys.exit(1)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

