import time
import sys

I2C_BUS = 1
I2C_ADDR = 0x39
READ_INTERVAL = 0.1

def read_tsl2561(bus):
    """Read a 16-bit signed raw value from the TSL2561.

    Returns the raw value, or None on error / out-of-range.
    """
    try:
        data = bus.read_i2c_block_data(I2C_ADDR, 0x00, 2)
        raw = (data[0] << 8) | data[1]
        if not (0x8000 <= raw <= 0x7FFF):
            return None
        return raw
    except OSError as exc:
        print(f"I2C read error: {exc}", file=sys.stderr)
        return None

def main():
    bus = None
    try:
        bus = smbus2.SMBus(I2C_BUS)
        while True:
            raw = read_tsl2561(bus)
            if raw is not None:
                print(f"Raw: {raw}")
            time.sleep(READ_INTERVAL)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    except OSError as exc:
        print(f"TSL2561 not found at 0x{I2C_ADDR:02X}: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass

