import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

INA219_ADDR = 0x1d
NUM_READINGS = 5
DELAY_SECONDS = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_ina219(bus, address):
    """Read a single INA219 measurement block from the device."""
    try:
        write_msg = i2c_msg.write(address, [0x01])
        read_msg = i2c_msg.read(address, 6)
        bus.i2c_rdwr(write_msg, read_msg)
        data = list(read_msg)
    except OSError as exc:
        raise RuntimeError(f"INA219 read failed at 0x{address:02X}: {exc}") from exc

    if len(data) < 6:
        raise RuntimeError(f"Short read from INA219 at 0x{address:02X}: {data}")

    # INA219 block layout: [meas_adc_msb, meas_adc_lsb, shunt_adc_msb, shunt_adc_lsb,
    #              channel_id, data_ok]
    meas_adc = (data[0] << 8) | data[1]
    shunt_adc = (data[2] << 8) | data[3]
    channel_id = data[4]
    data_ok = data[5]

    if channel_id != 0:
        raise RuntimeError(f"Unexpected channel ID: 0x{channel_id:02X}")
    if not data_ok:
        raise RuntimeError("INA219 data_ok bit not set")

    return meas_adc, shunt_adc

def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    bus = None
    try:
        bus = SMBus(1)
    except OSError as exc:
        print(f"Error: cannot open I2C bus 1: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        for i in range(NUM_READINGS):
            if not _running:
                break

            try:
                meas_adc, shunt_adc = read_ina219(bus, INA219_ADDR)
                print(f"Reading {i + 1}/{NUM_READINGS}: "
                      f"meas_adc={meas_adc:05X}  shunt_adc={shunt_adc:05X}")
            except RuntimeError as exc:
                print(f"Reading {i + 1}/{NUM_READINGS} failed: {exc}",
                      file=sys.stderr)

            if i < NUM_READINGS - 1 and _running:
                time.sleep(DELAY_SECONDS)

    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass

if __name__ == "__main__":
    main()

