from gpiozero import DistanceSensor
from gpiozero.exc import GPIOZeroError, DeviceClosed

# BCM pin assignments for the HC-SR04
SENSOR_TRIGGER_PIN = 18
SENSOR_ECHO_PIN = 23
SENSOR_ERROR_PIN = 24

# Timing constants (HC-SR04 max range ~4 m, 500 µs to 2 s response)
TRIGGER_PULSE_S = 1e-5
ECHO_SETTLE_S = 0.02
ECHO_TIMEOUT_S = 0.05

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    sensor = None
    try:
        sensor = DistanceSensor(
            echo=SENSOR_ECHO_PIN,
            trigger=SENSOR_TRIGGER_PIN,
            error=SENSOR_ERROR_PIN,
            max_distance=4.0,
        )
        print(f"HC-SR04 ready on trigger=GPIO{SENSOR_TRIGGER_PIN}, "
              f"echo=GPIO{SENSOR_ECHO_PIN}, error=GPIO{SENSOR_ERROR_PIN}")

        while _running:
            try:
                distance = sensor.distance * 100  # meters
                if distance < 0 or distance > 400:
