            except DeviceClosed:
                print("Error: sensor device closed unexpectedly.")
                break
            except Exception as exc:
                print(f"Error: {exc}")
                break

            # Wait for next reading, but check for shutdown signal
            for _ in range(int(ECHO_TIMEOUT_S * 10)):
                if not _running:
                    break
                time.sleep(0.01)

    except GPIOZeroError as exc:
        print(f"GPIO initialization error: {exc}")
    except Exception as exc:
        print(f"Unexpected error: {exc}")
