import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PINS = [4, 5, 6, 13, 17, 22, 27]

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    for pin in PINS:
        try:
            dev = OutputDevice(pin)
            devices.append(dev)
        except GPIOZeroError as exc:
            print(f"Failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
            for d in devices:
                d.close()
            sys.exit(1)

    try:
        while _running:
            for dev in devices:
                try:
                    dev.value = 1
                except DeviceClosed:
                    print(f"Device on GPIO {dev.pin} closed unexpectedly", file=sys.stderr)
                    devices.remove(dev)
                    break
                except GPIOZeroError as exc:
                    print(f"Error writing to GPIO {dev.pin}: {exc}", file=sys.stderr)
                    break
            time.sleep(0.01)
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

import signal
import sys
import time

from gpiozero import PWMOutputDevice
from gpiozero.exc import GPIOZeroError

PWM_PINS = [12, 13, 18, 19, 22, 23]

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    devices = []
    try:
        for pin in PWM_PINS:
            try:
                dev = PWMOutputDevice(pin, initial_value=0.0, frequency=100)
                devices.append(dev)
            except GPIOZeroError as exc:
                print(f"Failed to initialize PWM on GPIO{pin}: {exc}", file=sys.stderr)
                for d in devices:
                    d.close()
                sys.exit(1)

        while _running:
            values = []
            for dev in devices:
                try:
                    values.append(round(dev.value * 100, 2))
                except GPIOZeroError as exc:
                    print(f"Error reading GPIO{dev.pin}: {exc}", file=sys.stderr)
                    break

            if all(v == 0.0 for v in values):
                print("All GPIO pins set to 0%")
            elif all(v == 100.0 for v in values):
                print("All GPIO pins set to 100%")
            else:
                print(f"GPIO values: {values}")

            for dev in devices:
                try:
                    dev.value = 0.0
                except GPIOZeroError:
                    break

            if _running:
                time.sleep(2)

    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

import signal
import sys
import time

from smbus2 import SMBus

I2C_BUS = 1
I2C_ADDR = 0x27
POLL_INTERVAL = 2.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_pcf8574(bus, addr):
    """Read a single byte from the PCF8574; return None on error."""
    try:
        return bus.read_byte_data(addr, 0x00)
    except OSError:
        return None

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Failed to open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            raw = read_pcf8574(bus, I2C_ADDR)
            if raw is None:
                print("Error: no response from PCF8574 at 0x27", file=sys.stderr)
                time.sleep(POLL_INTERVAL)
                continue

            print(f"PCF8574 raw: 0x{raw:02X}")
            time.sleep(POLL_INTERVAL)
    finally:
        bus.close()
        print("\nI2C bus closed. Exiting.")

if __name__ == "__main__":
    main()

