import signal
import sys
import time

from picamera2 import Picamera2
from picamera2.encoders import JpegEncoder
from picamera2.outputs import FileOutput

running = True

def _handle_signal(signum, frame):
    global running
    running = False

def capture_image(picam2, filename):
    """Capture a single still image and save it to *filename*."""
    try:
        picam2.start()
    except Exception as exc:
        print(f"Error: failed to start camera: {exc}", file=sys.stderr)
        return False

    try:
        picam2.capture_file(filename)
    except Exception as exc:
        print(f"Error: capture failed: {exc}", file=sys.stderr)
        return False

    try:
        picam2.stop()
    except Exception as exc:
        print(f"Error: failed to stop camera: {exc}", file=sys.stderr)
        return False

    return True

def main():
    global running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    picam2 = Picamera2()

    try:
        output = FileOutput(filename="image.jpg")
        encoder = JpegEncoder()
        picam2.start_encoder(encoder, output)
    except Exception as exc:
        print(f"Error: failed to configure camera: {exc}", file=sys.stderr)
        return 1

    try:
        for i in range(3):
            if not running:
                break
            if not capture_image(picam2, "image.jpg"):
                return 1
            print(f"Cycle {i + 1}: image saved successfully.")
            time.sleep(1)
    finally:
        try:
            picam2.stop_encoder()
        except Exception:
            pass
        try:
            picam2.stop()
        except Exception:
            pass
        try:
            picam2.close()
        except Exception:
            pass

    return 0

if __name__ == "__main__":
    sys.exit(main())

import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
I2C_ADDR = 0x29
READ_INTERVAL_S = 1.0

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _read_raw_value(bus: SMBus, handle: int) -> int | None:
    """Read a 16-bit big-endian value from the TCS34725 raw register."""
    try:
        write_msg = i2c_msg.write(I2C_ADDR, [handle])
        read_msg = i2c_msg.read(I2C_ADDR, 2)
        bus.i2c_rdwr(write_msg, read_msg)
        return int.from_bytes(bytes(read_msg.buf[0:2]), byteorder="big")
    except OSError as exc:
        print(f"I2C read error: {exc}", file=sys.stderr)
        return None


def _check_valid(raw: int) -> bool:
    """Return True only if the raw value is a valid TCS34725 reading."""
    return 0 <= raw <= 0xFFFF


def main() -> int:
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        return 1

    try:
        while _running:
            try:
                handle = _read_raw_value(bus, 0)
            except OSError as exc:
                print(f"Device absent or bus error: {exc}", file=sys.stderr)
                break

            if handle is None or not _check_valid(handle):
                print("Invalid reading (out of range or device absent); skipping.", file=sys.stderr)
            else:
                print(f"Raw: {handle:04X}")

            # Sleep in small increments so signals are caught promptly
            slept = 0.0
            while _running and slept < READ_INTERVAL_S:
                time.sleep(0.05)
                slept += 0.05

    finally:
        bus.close()

    return 0


if __name__ == "__main__":
    sys.exit(main())

import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

INA219_ADDR = 0x40
NUM_READINGS = 60
DELAY_SECONDS = 1.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_ina219(bus, address):
    """Read a single 32-bit measurement from the INA219."""
    try:
        write_msg = i2c_msg.write(address, [0x01])
        read_msg = i2c_msg.read(address, 8)
        bus.i2c_rdwr(write_msg, read_msg)
        return bytes(read_msg)
    except OSError as exc:
        raise RuntimeError(f"INA219 read failed at 0x{address:02X}: {exc}") from exc

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(1)
    except OSError as exc:
        print(f"Error: cannot open I2C bus 1: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running and readings_remaining() > 0:
            try:
                data = read_ina219(bus, INA219_ADDR)
                print(data.hex(" "))
                readings_remaining() -= 1
            except RuntimeError as exc:
                print(exc, file=sys.stderr)
                break
            if _running and readings_remaining() > 0:
                time.sleep(DELAY_SECONDS)
    finally:
        bus.close()

def readings_remaining():
    return NUM_READINGS - (time.monotonic() - start_time) % NUM_READINGS

if __name__ == "__main__":
    start_time = time.monotonic()
    main()

import time
import signal
import sys
from smbus2 import SMBus, i2c_msg

INA219_ADDR = 0x17
MEAS_REG = 0x00
MEAS_LSB = 0x00
MEAS_MSB = 0x01

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def _swap_bytes(word):
    return ((word & 0xFF00) >> 8) | ((word & 0x00FF) << 8)

def _to_signed16(word):
    return word - 65536 if word >= 32768 else word

def read_ina219(bus):
    msg = i2c_msg.read(INA219_ADDR, 3)
    bus.i2c_rdwr(msg)
    data = list(msg)
    if len(data) < 3:
        raise IOError("Incomplete INA219 read")
    raw = _swap_bytes(data[0]) | (_swap_bytes(data[1]) << 8)
    return _to_signed16(raw)

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        bus = SMBus(1)
    except OSError as e:
        print(f"Failed to open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                val = read_ina219(bus)
            except OSError as e:
                print(f"I2C read error: {e}", file=sys.stderr)
                time.sleep(5)
                continue

            if val < 0 or val > 16383:
                print(f"Warning: measurement {val} out of signed16 range", file=sys.stderr)

            print(f"Current Current: {val}")
            time.sleep(5)
    finally:
        bus.close()

if __name__ == "__main__":
    main()

import time
import signal
import sys
import board
import adafruit_dht

# Global handle so the signal handler can release the sensor.
_sensor = None

def cleanup():
    """Release the DHT22 sensor if it was opened."""
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None

def signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for a clean shutdown."""
    cleanup()
    sys.exit(0)

def main():
    global _sensor

    # Register signal handlers for graceful termination.
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize the DHT22 on the three-channel GPIO bus.
    try:
        _sensor = adafruit_dht.DHT22(board.D4, use_pulseio=False)
    except Exception as exc:
        print(f"Failed to initialize DHT22 on GPIO 4: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while True:
            try:
                temperature = _sensor.temperature
                humidity = _sensor.humidity
                if temperature is not None and humidity is not None:
                    print(f"Temperature: {temperature:.1f} C  Humidity: {humidity:.1f} %")
                else:
                    print("Sensor returned None for temperature or humidity.")
            except RuntimeError as exc:
                # DHT22 checksum / timing glitches are common; retry next cycle.
                print(f"Sensor read error: {exc}", file=sys.stderr)
            except Exception as exc:
                print(f"Unexpected error reading sensor: {exc}", file=sys.stderr)

            time.sleep(1)
    finally:
        cleanup()

if __name__ == "__main__":
    main()

