import time
import signal
import sys
import board
import adafruit_dht

# Global handle so the signal handler can release it.
_sensor = None
_running = True


def _cleanup():
    """Release the DHT22 sensor if it was opened."""
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def main():
    global _sensor

    # Install signal handlers for clean exit on Ctrl-C / kill.
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize the DHT22 on GPIO 22 (BCM) via adafruit-circuitpython-dht.
    try:
        _sensor = adafruit_dht.DHT22(board.D22, use_pulseio=False)
    except Exception as exc:
        print(f"Failed to initialize DHT22 on GPIO 22: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    # Report the state applied to stdout.
    print("DHT22 reporting started. Press Ctrl-C to stop.")

    try:
        for i in range(2):
            if not _running:
                break

            try:
                temp = _sensor.temperature
                humidity = _sensor.humidity

                # adafruit_dht may return None on a transient read failure.
                if temp is None or humidity is None:
                    print("  Cycle {}: no data (device may be absent or busy).")
                else:
                    print(f"  Cycle {i + 1}: temp={temp:.1f} C  humidity={humidity:.1f} %")

            except RuntimeError as exc:
                # DHT22 checksum / timing glitches are common; give up.
                print(f"  Cycle {i + 1}: read error ({exc}).", file=sys.stderr)
            except Exception as exc:
                # Unexpected error (e.g., GPIO bus fault).
                print(f"  Cycle {i + 1}: unexpected error ({exc}).", file=sys.stderr)

            if i < 1:
                time.sleep(3)

    finally:
        _cleanup()
        print("DHT22 reporting stopped.")


if __name__ == "__main__":
    main()

