import signal
import sys
import time

from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError, DeviceClosed

PIN_17 = 17
PIN_18 = 18
INTERVAL = 5.0

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        output17 = OutputDevice(PIN_17)
        output18 = OutputDevice(PIN_18)
    except GPIOZeroError as exc:
        print(f"Error: failed to initialize GPIO pins {PIN_17}/{PIN_18}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                state17 = output17.value
                state18 = output18.value
            except DeviceClosed:
                print("Error: GPIO device was closed unexpectedly.", file=sys.stderr)
                break
            except GPIOZeroError as exc:
                print(f"Error: failed to read GPIO state: {exc}", file=sys.stderr)
                break

            if not (state17 == 1 or state17 == 0):
                print(f"GPIO 17 state: {state17}", file=sys.stderr)
                break
            if not (state18 == 1 or state18 == 0):
                print(f"GPIO 18 state: {state18}", file=sys.stderr)
                break

            print(f"GPIO 17: {state17}, GPIO 18: {state18}")

            for _ in range(int(INTERVAL * 10)):
                if not _running:
                    break
                time.sleep(0.1)

    finally:
        try:
            output17.close()
            output18.close()
        except Exception:
            pass
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

import signal
