import signal
import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

# BCM pin numbers for the three outputs
PINS = (5, 6, 12)

# Global list so the signal handler can release every device
_devices = []

def cleanup(*_):
    """Release every gpiozero device on exit."""
    for dev in _devices:
        try:
            dev.close()
        except Exception:
            pass
    _devices.clear()
    sys.exit(0)

def main():
    global _devices
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    for pin in PINS:
        try:
            dev = OutputDevice(pin)
            _devices.append(dev)
        except GPIOZeroError as exc:
            print(f"Failed to initialize GPIO {pin}: {exc}", file=sys.stderr)
            cleanup()
        except Exception as exc:
            print(f"Unexpected error on GPIO {pin}: {exc}", file=sys.stderr)
            cleanup()

    for i in range(3):
        try:
            dev.on()
            print(f"Cycle {i+1}: GPIO {PINS[i]} -> ON")
        except GPIOZeroError as exc:
            print(f"Cycle {i+1}: GPIO {PINS[i]} write error: {exc}", file=sys.stderr)
            cleanup()
        except Exception as exc:
            print(f"Cycle {i+1}: GPIO {PINS[i]} error: {exc}", file=sys.stderr)
            cleanup()

    print("Program finished.")

if __name__ == "__main__":
    main()

