import signal
import sys
import smbus2

PCA9685_ADDR = 0x40

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def read_pca9685(bus, addr):
    """Read a single 16-bit value from the PCA9685."""
    # The PCA9685 is an I2C peripheral; we read the low byte first.
    data = bus.read_i2c_block_data(addr, 0x00, 2)
    return data[0] | (data[1] << 8)

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = smbus2.SMBus(1)
    except OSError as e:
        print(f"Failed to open I2C bus 1: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running:
            try:
                value = read_pca9685(bus, PCA9685_ADDR)
            except OSError as e:
                print(f"I2C read error: {e}", file=sys.stderr)
                break

            print(value)
    finally:
        bus.close()

if __name__ == "__main__":
    main()

