import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
MPU6050_ADDR = 0x68

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _read_word(bus, addr, reg):
    """Read a 16-bit unsigned value from two consecutive registers."""
    write_msg = i2c_msg.write(addr, [reg])
    read_msg = i2c_msg.read(addr, 2)
    bus.i2c_rdwr(write_msg, read_msg)
    return int.from_bytes(bytes(read_msg.buf[0:2]), byteorder='big')


def _read_block(bus, addr, reg, length):
    """Read a block of bytes from consecutive registers."""
    write_msg = i2c_msg.write(addr, [reg])
    read_msg = i2c_msg.read(addr, length)
    bus.i2c_rdwr(write_msg, read_msg)
    return bytes(read_msg.buf)


def _validate_word(word):
    """Return True if the word is a valid signed 16-bit value."""
    if not (0 <= word <= 0xFFFF):
        return False
    return word & 0x8000 == 0


def _validate_block(block):
    """Return True if the block is a valid signed 16-bit little-endian array."""
    if not (0 <= len(block) <= 0xFFFF):
        return False
    if not _validate_word(block[0]):
        return False
    for i in range(1, len(block)):
        if not _validate_word(block[i]):
            return False
    return True


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    bus = None
    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        try:
            bus.read_byte(MPU6050_ADDR)
        except OSError as exc:
            print(f"Error: no device found at 0x{MPU6050_ADDR:02X} on bus {I2C_BUS}: {exc}", file=sys.stderr)
            return

        while _running:
            try:
                raw_accel_x = _read_word(bus, MPU6050_ADDR, 0x3B)
                raw_accel_y = _read_word(bus, MPU6050_ADDR, 0x3D)
                raw_accel_z = _read_word(bus, MPU6050_ADDR, 0x3F)

                if not _validate_word(raw_accel_x) or not _validate_word(raw_accel_y) or not _validate_word(raw_accel_z):
                    print("Warning: invalid accelerometer data (out of signed 16-bit range).")
                    continue

                accel_x = raw_accel_x / 16384.0
                accel_y = raw_accel_y / 16384.0
                accel_z = raw_accel_z / 16384.0

                print(f"Accel X: {accel_x:.3f}, Accel Y: {accel_y:.3f}, Accel Z: {accel_z:.3f}")

            except OSError as exc:
                print(f"Error: I2C communication failure: {exc}", file=sys.stderr)
                break

            time.sleep(0.1)

    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass


if __name__ == "__main__":
    main()

