import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
MPU6050_ADDR = 0x68
NUM_READINGS = 8
DELAY_SECONDS = 0.1

_running = True

def _handle_signal(signum, frame):
    global _running
    _running = False

def _check_error(code, label):
    if code == 0:
        return True
    print(f"Error reading MPU6050 (code {code}): {label}", file=sys.stderr)
    return False

def _read_word(bus, addr, label):
    try:
        write_msg = i2c_msg.write(addr, [label])
        read_msg = i2c_msg.read(addr, 2)
        bus.i2c_rdwr(write_msg, read_msg)
        data = list(read_msg)
    except OSError as e:
        print(f"{label}: I2C transfer failed: {e}", file=sys.stderr)
        return None
    if len(data) < 2:
        print(f"{label}: short read", file=sys.stderr)
        return None
    return (data[0] << 8) | data[1]

def _read_block(bus, addr, label, length):
    try:
        write_msg = i2c_msg.write(addr, [label])
        read_msg = i2c_msg.read(addr, length)
        bus.i2c_rdwr(write_msg, read_msg)
        return list(read_msg)
    except OSError as e:
        print(f"{label}: I2C transfer failed: {e}", file=sys.stderr)
        return None

def read_mpu6050(bus, addr):
    raw_ax = _read_word(bus, addr, "raw_ax")
    raw_ay = _read_word(bus, addr, "raw_ay")
    raw_az = _read_word(bus, addr, "raw_az")
    raw_glon = _read_block(bus, addr, "raw_glon", 2)
    raw_glat = _read_block(bus, addr, "raw_glat", 2)
    raw_gyr_x = _read_word(bus, addr, "raw_gyr_x")
    raw_gyr_y = _read_word(bus, addr, "raw_gyr_y")
    raw_gyr_z = _read_word(bus, addr, "raw_gyr_z")
    raw_acc_x = _read_word(bus, addr, "raw_acc_x")
    raw_acc_y = _read_word(bus, addr, "raw_acc_y")
    raw_acc_z = _read_word(bus, addr, "raw_acc_z")
    return {
        "ax": raw_ax, "ay": raw_ay, "az": raw_az,
        "glon": raw_glon[0], raw_glon[1],
        "glat": raw_glat[0], raw_glat[1],
        "gyr_x": raw_gyr_x, "gyr_y": raw_gyr_y, "gyr_z": raw_gyr_z,
        "acc_x": raw_acc_x, "acc_y": raw_acc_y, "acc_z": raw_acc_z,
    }

def main():
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        bus = SMBus(I2C_BUS)
    except OSError as e:
        print(f"Failed to open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running and (time.monotonic() < NUM_READINGS * DELAY_SECONDS):
            try:
                data = read_mpu6050(bus, MPU6050_ADDR)
            except OSError as e:
                print(f"Device unavailable: {e}", file=sys.stderr)
                break

            if _check_error(data, "MPU6050 read"):
                parts = data.get("ax", 0)
                if parts < -32768 or parts > 32767:
                    print("Warning: ax out of signed 16-bit range", file=sys.stderr)
                print(data)
            else:
                print("Warning: invalid reading", file=sys.stderr)

            time.sleep(DELAY_SECONDS)
    finally:
        try:
            bus.close()
        except OSError:
            pass

if __name__ == "__main__":
    main()

