import serial
import time
import sys

PORT = '/dev/serial0'
BAUD = 9600
READ_COUNT = 3
DELAY_SEC = 2

def main():
    ser = None
    try:
        ser = serial.Serial(PORT, BAUD, timeout=1)
        print(f"Opened {PORT} @ {BAUD} baud")

        for i in range(1, READ_COUNT + 1):
            try:
                line = ser.readline().decode('ascii', errors='replace').strip()
                if line:
                    print(f"Reading {i}/{READ_COUNT}: {line}")
                else:
                    print(f"Reading {i}/{READ_COUNT}: <empty line>")
            except serial.SerialException as e:
                print(f"Reading {i}/{READ_COUNT}: serial error: {e}")
                break
            except OSError as e:
                print(f"Reading {i}/{READ_COUNT}: I/O error: {e}")
                break

            if i < READ_COUNT:
                time.sleep(DELAY_SEC)

        print("Data exchange sequence completed.")

    except serial.SerialException as e:
        print(f"Error: could not open {PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    except OSError as e:
        print(f"Error: {PORT} not found or inaccessible: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        if ser is not None and ser.is_open:
            ser.close()
            print("Serial port closed.")

