import signal
import sys
import time

from smbus2 import SMBus, i2c_msg

I2C_BUS = 1
TSL2591_ADDR = 0x29
NUM_READINGS = 3
READ_INTERVAL_S = 10

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def _write_register(bus, reg, value):
    bus.write_byte_data(TSL2591_ADDR, reg, value)


def _read_register(bus, reg):
    return bus.read_byte_data(TSL2591_ADDR, reg)


def _read_block(bus, reg, length):
    return bus.read_i2c_block_data(TSL2591_ADDR, reg, length)


def _check_error(value):
    return value & 0x08 == 0


def _check_valid_reading(value):
    return (value & 0x07) == 0


def _read_tsl2591(bus):
    """Read a 16-bit signed raw value from the TSL2591.

    Returns the raw value, or None if the device is absent or the read fails.
    """
    try:
        data = _read_block(bus, 0x00, 2)
    except OSError:
        return None

    if len(data) < 2:
        return None

    raw = (data[0] << 8) | data[1]
    if _check_valid_reading(raw):
        return raw
    return None


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    bus = None
    try:
        bus = SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        sys.exit(1)

    try:
        while _running and bus is not None:
            try:
                raw = _read_tsl2591(bus)
            except OSError as exc:
                print(f"Error: TSL2591 not responding at 0x{TSL2591_ADDR:02X}: {exc}", file=sys.stderr)
                break

            if raw is None:
                print("Error: no valid reading from TSL2591", file=sys.stderr)
                break

            print(f"Raw: {raw}")

            for _ in range(NUM_READINGS):
                if not _running:
                    break
                time.sleep(READ_INTERVAL_S)
    finally:
        if bus is not None:
            try:
                bus.close()
            except OSError:
                pass


if __name__ == "__main__":
    main()

