    finally:
        for dev in devices:
            try:
                dev.close()
            except Exception:
                pass
        print("GPIO cleanup done.")

if __name__ == "__main__":
    main()

import smbus2
import time
import sys

I2C_BUS = 1
I2C_ADDR = 0x1d
READ_INTERVAL_S = 1.0

def main() -> int:
    try:
        bus = smbus2.SMBus(I2C_BUS)
    except OSError as exc:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        return 1

    try:
        while True:
            try:
                data = bus.read_i2c_block_data(I2C_ADDR, 0x00, 2)
                # ADXL345: X, Y, Z, MSB, LSB, XL, XH, YL, YH, ZL, ZH, ZXL, ZXH
                raw_x = (data[0] << 8) | data[1]
                raw_y = (data[2] << 8) | data[3]
                raw_z = (data[4] << 8) | data[5]
                # Convert to signed 16-bit
                if raw_x >= 0x8000:
                    raw_x -= 0x10000
                if raw_y >= 0x8000:
                    raw_y -= 0x10000
                if raw_z >= 0x8000:
                    raw_z -= 0x10000
                # Scale: 16-bit signed -> 10-bit resolution (0.125 mg/LSB)
                x_g = raw_x / 0x1000
                y_g = raw_y / 0x1000
                z_g = raw_z / 0x1000
                print(f"X: {x_g:.3f} g, Y: {y_g:.3f} g, Z: {z_g:.3f} g")
            except OSError as exc:
                print(f"Warning: I2C read failed: {exc}", file=sys.stderr)

            time.sleep(READ_INTERVAL_S)
    except KeyboardInterrupt:
        print("\nInterrupted by user.")
    finally:
        try:
            bus.close()
        except Exception:
            pass

    return 0

if __name__ == "__main__":
    sys.exit(main())

