import time
import signal
import sys
import board
import adafruit_dht

# Global handle so the signal handler can release it.
_sensor = None
_running = True


def _cleanup():
    """Release the DHT22 sensor if it was opened."""
    global _sensor
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None


def _handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


def main():
    global _sensor

    # Install signal handlers for clean exit on Ctrl-C / kill.
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    # Initialize the DHT22 on GPIO 4 (BCM) via adafruit-circuitpython-dht.
    try:
        _sensor = adafruit_dht.DHT22(board.D4, use_pulseio=False)
    except Exception as exc:
        print(f"Failed to initialize DHT22 on GPIO 4: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    try:
        for i in range(3):
            if not _running:
                break

            try:
                temp = _sensor.temperature
                humidity = _sensor.humidity

                # adafruit_dht may return None on a failed read.
                if temp is None or humidity is None:
                    print("DHT22 read returned None — skipping cycle.", file=sys.stderr)
                else:
                    print(f"Cycle {i + 1}: Temperature = {temp:.1f} °C  "
                          f"Humidity = {humidity:.1f} %")

            except RuntimeError as exc:
                # DHT22 checksum / timing errors are common; log and continue.
                print(f"Cycle {i + 1} read error: {exc}", file=sys.stderr)
            except Exception as exc:
                # Unexpected error — log and continue.
                print(f"Cycle {i + 1} unexpected error: {exc}", file=sys.stderr)

            if i < 2 and _running:
                time.sleep(5)

    finally:
        _cleanup()
        print("Program finished.")


if __name__ == "__main__":
    main()

